import{chooseNext,validate}from'./player.mjs';import{AudioDirector}from'./audio-director.mjs';
const $=id=>document.getElementById(id),stage=$('stage'),voice=$('voice'),ambient=$('ambient');let quotes=[],current,remaining=[],hideTimer,statusTimer,imageEpoch=0;let first=true,visible=false;
const storage={get(k){try{return localStorage.getItem(k)}catch{return null}},set(k,v){try{localStorage.setItem(k,v)}catch{}}};
function message(s,timeout=6000){$('status').textContent=s;clearTimeout(statusTimer);if(timeout)statusTimer=setTimeout(()=>$('status').textContent='',timeout);}
const director=new AudioDirector(ambient,voice,{wanted:storage.get('tc-music')!=='off',onState(s){$('play-icon').textContent=s.speaking?'■':'▶';$('play-label').textContent=s.speaking?'Dừng':'Nghe';$('play').setAttribute('aria-label',s.speaking?'Dừng đọc câu':'Nghe câu tiếng Trung');const playing=!ambient.paused&&!s.suspended;$('music').setAttribute('aria-pressed',String(s.wanted));$('music').setAttribute('aria-label',s.wanted?'Tắt nhạc nền':'Bật nhạc nền');$('music-icon').textContent=s.wanted?(playing?'♫':'♩'):'♪';},onError(kind){message(kind==='music'?'Nhạc chưa phát được. Chạm nút nhạc để thử lại.':'Chưa phát được giọng đọc. Bấm Nghe để thử lại.');}});
function reveal(value){visible=value;stage.classList.toggle('revealed',value);$('controls').inert=!value;clearTimeout(hideTimer);if(value)hideTimer=setTimeout(()=>{if(!$('controls').contains(document.activeElement)&&!director.speaking)reveal(false);},5500);}
function unlock(){if(first){first=false;stage.classList.add('started');director.unlock();reveal(true);return true;}return false;}
function interact(){if(!unlock())reveal(!visible);}
async function show(q){director.stopVoice();current=q;const epoch=++imageEpoch;for(const k of['hanzi','pinyin','vietnamese'])$(k).textContent=q[k];$('count').textContent=String(quotes.indexOf(q)+1).padStart(2,'0')+' / '+quotes.length;$('download').href=q.download;$('download').download=`Tu-Canh-${q.id}-${q.width}x${q.height}.jpg`;$('source-title').textContent=q.source.title;$('source-artist').textContent=q.source.artist;$('source-link').href=q.source.source;storage.set('tu-canh-current',q.id);$('play').disabled=true;const img=new Image();img.src=q.scene_image;try{await img.decode();if(epoch!==imageEpoch)return;$('background').src=q.scene_image;$('background').alt=q.art_alt;$('backdrop').style.backgroundImage=`url('${q.scene_image}')`;}catch{if(epoch===imageEpoch)message('Ảnh chưa tải được. Chạm Câu tiếp để thử ảnh khác.');}if(epoch===imageEpoch){$('play').disabled=false;$('play').setAttribute('aria-label',q.audio_status==='ready'?'Nghe câu tiếng Trung':'Giọng đọc đang được chuẩn bị');}const next=quotes.find(x=>x.id!==q.id);if(next){const preload=new Image();preload.src=next.scene_image;}}
stage.addEventListener('click',e=>{if(e.target.closest('button,a'))return;interact();});stage.addEventListener('keydown',e=>{if(e.target!==stage)return;if(e.key==='Enter'||e.key===' '){e.preventDefault();interact();}});$('controls').addEventListener('focusin',()=>reveal(true));$('controls').addEventListener('pointerdown',()=>clearTimeout(hideTimer));$('play').addEventListener('click',()=>{unlock();reveal(true);if(director.speaking)director.stopVoice();else if(current.audio_status==='ready')director.speak(current.audio);else message('Giọng đọc đang được chuẩn bị. Bạn có thể xem và tải artwork.');});$('next').addEventListener('click',()=>{unlock();reveal(true);show(chooseNext(quotes,remaining,current));});$('download').addEventListener('click',()=>{unlock();reveal(true);});$('music').addEventListener('click',()=>{if(first){first=false;stage.classList.add('started');reveal(true);if(!director.wanted)director.wanted=true;director.unlock();}else director.toggle();storage.set('tc-music',director.wanted?'on':'off');});$('info').addEventListener('click',()=>{unlock();$('about').showModal();});$('close-info').addEventListener('click',()=>$('about').close());document.addEventListener('visibilitychange',()=>director.suspend(document.hidden));window.addEventListener('pagehide',()=>director.suspend(true));window.addEventListener('pageshow',()=>director.suspend(document.hidden));
fetch('./quotes.json').then(r=>{if(!r.ok)throw Error();return r.json()}).then(d=>{quotes=validate(d);const saved=storage.get('tu-canh-current');current=quotes.find(q=>q.id===saved)||quotes[0];remaining=quotes.filter(q=>q.id!==current.id).map(q=>q.id);show(current);$('next').disabled=false;}).catch(()=>{message('Chưa mở được thư viện. Hãy tải lại trang.',0);});
